"""MP4 header probe over generated bytes. No real media; nothing here touches the disk."""
import json
import random
import time
import unittest

import mkvgen
import mp4gen
from kura import mkvprobe, mp4probe, probe as probe_mod
from kura.mp4probe import probe

MIB = 1 << 20
box, u16, u32, u64 = mp4gen.box, mp4gen.u16, mp4gen.u32, mp4gen.u64


class Source:
    """A byte source that records every read the probe makes."""

    def __init__(self, data):
        self.data, self.size, self.reads = bytes(data), len(data), []

    def __call__(self, offset, n):
        self.reads.append((offset, n))
        return self.data[offset:offset + n]

    @property
    def largest(self):
        return max((n for _, n in self.reads), default=0)

    @property
    def total(self):
        return sum(n for _, n in self.reads)

    def touched(self, start, end):
        return any(o < end and o + n > start for o, n in self.reads)


def run(data, **kw):
    src = Source(data)
    return probe(src, src.size, **kw), src


def printable(value):
    if isinstance(value, str):
        return len(value) <= 200 and value.isprintable()
    if isinstance(value, dict):
        return all(printable(k) and printable(v) for k, v in value.items())
    if isinstance(value, list):
        return all(printable(v) for v in value)
    return True


class Layouts(unittest.TestCase):
    def test_faststart_document(self):
        result, src = run(mp4gen.build())
        self.assertEqual((result["status"], result["container"], result["warnings"]), ("ok", "mp4", []))
        self.assertEqual(result["duration_s"], 1420.0)
        self.assertEqual(result["writing_app"], "Lavf59.27.100")
        video = result["video"]
        self.assertEqual((video["track"], video["codec_id"], video["codec"], video["profile"], video["bit_depth"]),
                         (1, "avc1", "h264", "high", 8))
        self.assertEqual((video["width"], video["height"], video["fps"]), (1920, 1080, 23.976))
        self.assertEqual(video["bitrate_source"], "size_over_duration")
        self.assertEqual(result["attachments"], {"count": 0, "fonts": 0, "bytes": 0, "names": []})
        self.assertEqual(set(result), set(json.loads(json.dumps(result))))
        self.assertTrue(printable(result))
        self.assertLessEqual(src.largest, mp4probe.CLUSTER_CAP)

    def test_same_keys_as_the_matroska_document(self):
        raw = mkvgen.build()
        mkv = mkvprobe.probe(Source(raw), len(raw))
        mp4, _ = run(mp4gen.build())
        self.assertEqual(set(mp4), set(mkv))
        self.assertEqual(set(mp4["video"]), set(mkv["video"]))
        self.assertEqual(set(mp4["audio"][0]), set(mkv["audio"][0]))
        self.assertEqual(set(mp4["subtitles"][0]), set(mkv["subtitles"][0]))
        self.assertEqual(set(mp4["encoder"]), set(mkv["encoder"]))

    def test_moov_at_the_end_is_found_without_reading_mdat(self):
        data = mp4gen.build(faststart=False, codec="hevc", sei="private", settings=mkvgen.X265_TEXT,
                            mdat_pad=3 * MIB)
        start = len(mp4gen.FTYP)
        result, src = run(data)
        self.assertEqual((result["status"], result["warnings"]), ("ok", []))
        self.assertEqual(result["video"]["codec"], "hevc")
        self.assertFalse(src.touched(start + 8, start + 8 + 3 * MIB))
        self.assertLess(src.total, 8 << 10)

    def test_faststart_and_moov_at_the_end_agree(self):
        a, _ = run(mp4gen.build(faststart=True))
        b, _ = run(mp4gen.build(faststart=False))
        for key in ("duration_s", "video", "audio", "subtitles", "encoder"):
            self.assertEqual(a[key], b[key], key)

    def test_largesize_boxes(self):
        for kw in ({"mdat": "large"}, {"mdat": "large", "faststart": False, "wide": True}):
            with self.subTest(kw):
                result, _ = run(mp4gen.build(**kw))
                self.assertEqual((result["status"], result["encoder"]["where"]), ("ok", "first_frame"))

    def test_largesize_moov(self):
        data = mp4gen.build()
        i = data.index(b"moov") - 4
        moov = data[i:data.index(b"mdat") - 4]
        shifted = data[:i] + u32(1) + b"moov" + u64(len(moov) + 8) + moov[8:] + data[data.index(b"mdat") - 4:]
        # The 8 extra header bytes move every sample offset: patch the stco entries to match.
        at = shifted.index(b"stco") + 12
        old = int.from_bytes(shifted[at:at + 4], "big")
        shifted = shifted.replace(u32(old), u32(old + 8))
        result, _ = run(shifted)
        self.assertEqual((result["status"], result["video"]["codec"]), ("ok", "h264"))
        self.assertEqual(result["encoder"]["where"], "first_frame")

    def test_size_zero_last_box_runs_to_the_end_of_the_file(self):
        result, _ = run(mp4gen.build(mdat="size0"))
        self.assertEqual((result["status"], result["encoder"]["where"]), ("ok", "first_frame"))
        result, _ = run(mp4gen.build(faststart=False, mdat="size0"))       # it swallows the moov behind it
        self.assertEqual((result["status"], "no_moov" in result["warnings"]), ("invalid", True))
        # A size-0 moov at the very end.
        data = mp4gen.build(faststart=False)
        i = data.index(b"moov") - 4
        result, _ = run(data[:i] + u32(0) + data[i + 4:])
        self.assertEqual((result["status"], result["video"]["codec"]), ("ok", "h264"))

    def test_other_top_level_boxes_are_skipped(self):
        extra = box(b"free", bytes(100)) + box(b"skip", b"x") + box(b"wide") + box(b"uuid", bytes(32))
        result, _ = run(mp4gen.build(extra_top=extra))
        self.assertEqual((result["status"], result["warnings"]), ("ok", []))
        # A leading free/skip/wide box in place of ftyp still counts as MP4.
        data = box(b"free", bytes(8)) + mp4gen.build()[len(mp4gen.FTYP):]
        result, _ = run(data)
        self.assertEqual(result["container"], "mp4")

    def test_constant_sample_size_and_co64(self):
        entry = mp4gen.visual_entry(b"avc1", 640, 480, mp4gen.avcc())
        sample = mkvgen.frame([mkvgen.sei_nal("avc", [mkvgen.encoder_message(mkvgen.X264_TEXT)]),
                               mkvgen.slice_nal("avc")])
        stbl = (mp4gen.stsd(entry) + mp4gen.stts([(1, 1001)]) + mp4gen.stsz(1, constant=len(sample))
                + mp4gen.stco(0, wide=True))
        t = box(b"trak", mp4gen.tkhd(1, True, 640, 480) + box(b"mdia", mp4gen.mdhd(24000, 24000 * 60)
                + mp4gen.hdlr(b"vide") + box(b"minf", box(b"stbl", stbl))))
        moov = box(b"moov", mp4gen.mvhd(1000, 60_000) + t)
        offset = len(mp4gen.FTYP) + len(moov) + 8
        t = t.replace(u64(0), u64(offset))
        moov = box(b"moov", mp4gen.mvhd(1000, 60_000) + t)
        result, _ = run(mp4gen.FTYP + moov + box(b"mdat", sample))
        self.assertEqual((result["status"], result["encoder"]["library"]), ("ok", "x264"))
        self.assertEqual((result["video"]["width"], result["video"]["height"]), (640, 480))

    def test_version_1_headers(self):
        result, _ = run(mp4gen.build(v1=True))
        self.assertEqual((result["status"], result["duration_s"], result["video"]["width"]), ("ok", 1420.0, 1920))
        self.assertEqual(result["video"]["fps"], 23.976)


class Encoder(unittest.TestCase):
    def test_x264_settings_in_the_first_sample(self):
        result, src = run(mp4gen.build())
        enc = result["encoder"]
        self.assertEqual((enc["library"], enc["version"], enc["where"]), ("x264", "164 r3095 baee400", "first_frame"))
        self.assertEqual(enc["settings"]["crf"], "18.0")
        self.assertEqual(enc["settings"]["deblock"], "1:-1:-1")
        self.assertEqual(enc["settings"]["cabac"], "1")
        self.assertTrue(printable(result))

    def test_x264_settings_with_a_two_byte_nal_length(self):
        entry = mp4gen.visual_entry(b"avc1", 640, 480, mp4gen.avcc(length_size=2))
        sample = mkvgen.frame([mkvgen.sei_nal("avc", [mkvgen.encoder_message(mkvgen.X264_TEXT)]),
                               mkvgen.slice_nal("avc")], length_size=2)
        data = self.single(entry, sample)
        result, _ = run(data)
        self.assertEqual(result["encoder"]["library"], "x264")

    @staticmethod
    def single(entry, sample):
        def make(offset):
            stbl = mp4gen.stsd(entry) + mp4gen.stts([(1, 1001)]) + mp4gen.stsz(1, len(sample)) + mp4gen.stco(offset)
            trak = box(b"trak", mp4gen.tkhd(1, True, 640, 480) + box(b"mdia", mp4gen.mdhd(24000, 24000)
                       + mp4gen.hdlr(b"vide") + box(b"minf", box(b"stbl", stbl))))
            return box(b"moov", mp4gen.mvhd(1000, 1000) + trak)
        return mp4gen.FTYP + make(len(mp4gen.FTYP) + len(make(0)) + 8) + box(b"mdat", sample)

    def test_x265_settings_in_hvcc(self):
        data = mp4gen.build(codec="hevc", settings=mkvgen.X265_TEXT, sei="private")
        result, src = run(data)
        enc = result["encoder"]
        self.assertEqual((enc["library"], enc["where"]), ("x265", "codec_private"))
        self.assertEqual((enc["settings"]["crf"], enc["settings"]["preset"]), ("19.0", "slow"))
        self.assertEqual(enc["settings"]["wpp"], True)
        self.assertEqual(enc["settings"]["no-open-gop"], True)
        mdat = data.index(b"mdat")
        self.assertFalse(src.touched(mdat, len(data)))         # the first sample was never needed

    def test_x265_settings_in_the_first_sample(self):
        result, _ = run(mp4gen.build(codec="hevc", settings=mkvgen.X265_TEXT, sei="frame"))
        self.assertEqual((result["encoder"]["library"], result["encoder"]["where"]), ("x265", "first_frame"))

    def test_no_settings_is_a_warning_not_an_error(self):
        result, _ = run(mp4gen.build(settings=None, sei=None))
        self.assertEqual((result["status"], result["encoder"]), ("ok", None))
        self.assertEqual(result["warnings"], ["no_encoder_settings"])

    def test_bit_depth(self):
        for kw, expect in (({"codec": "hevc", "hevc_bits": 10}, ("hevc", "main10", 10)),
                           ({"codec": "hevc", "hevc_bits": 8}, ("hevc", "main10", 8)),
                           ({"avc_profile": 110, "avc_bit_depth": 10}, ("h264", "high10", 10)),
                           ({"avc_profile": 100}, ("h264", "high", 8)),
                           ({"codec": "av1", "hevc_bits": 10}, ("av1", "main", 10)),
                           ({"codec": "av1", "hevc_bits": 8}, ("av1", "main", 8)),
                           ({"codec": "av1", "hevc_bits": 12}, ("av1", "main", 12))):
            with self.subTest(kw):
                v = run(mp4gen.build(settings=None, sei=None, **kw))[0]["video"]
                self.assertEqual((v["codec"], v["profile"], v["bit_depth"]), expect)

    def test_a_cut_first_sample_is_clamped_to_the_cap(self):
        data = mp4gen.build(settings=None, sei=None)
        # The declared first-sample size is huge: the read stays under the cap.
        data = data.replace(u32(0) + u32(2) + u32(len(mkvgen.frame([mkvgen.slice_nal("avc")]))),
                            u32(0) + u32(2) + u32(0x7FFFFFFF), 1)
        result, src = run(data)
        self.assertLessEqual(src.largest, mp4probe.CLUSTER_CAP)
        self.assertEqual(result["status"], "ok")

    def test_budget_that_cannot_reach_the_sample_is_partial(self):
        data = mp4gen.build()
        full, _ = run(data)
        for budget in range(full["bytes_read"] - 200, full["bytes_read"], 20):
            result, src = run(data, max_bytes=budget)
            self.assertLessEqual(src.total, budget)
            if result["encoder"] is None:
                self.assertEqual(result["status"], "partial", budget)
                self.assertIn("budget_exhausted", result["warnings"], budget)


class Tracks(unittest.TestCase):
    def test_audio_and_subtitle_listing(self):
        data = mp4gen.build(audio=((b"mp4a", "jpn"), (b"ac-3", "eng"), (b"ec-3", "und"), (b"Opus", "fra"),
                                   (b"fLaC", "deu"), (b"zzzz", "spa")),
                            subs=((b"tx3g", "eng"), (b"wvtt", "jpn"), (b"stpp", "fra"), (b"xxxx", "und")),
                            audio_channels=6)
        result, _ = run(data)
        self.assertEqual([(a["track"], a["codec"], a["lang"]) for a in result["audio"]],
                         [(10, "aac", "jpn"), (11, "ac3", "eng"), (12, "eac3", "und"), (13, "opus", "fra"),
                          (14, "flac", "deu"), (15, "other", "spa")])
        self.assertEqual({(a["channels"], a["sample_rate"]) for a in result["audio"]}, {(6, 48000)})
        self.assertEqual([a["default"] for a in result["audio"]], [True] + [False] * 5)
        self.assertEqual([(s["track"], s["format"], s["lang"]) for s in result["subtitles"]],
                         [(30, "tx3g", "eng"), (31, "wvtt", "jpn"), (32, "stpp", "fra"), (33, "other", "und")])
        self.assertEqual([s["default"] for s in result["subtitles"]], [True, False, False, False])
        self.assertFalse(any(s["forced"] for s in result["subtitles"]))

    def test_aac_object_type_comes_from_esds(self):
        for obj, expect in ((0x40, "aac"), (0x69, "mp3"), (0x6B, "mp3"), (0xA5, "ac3"), (0xE1, "other")):
            with self.subTest(obj):
                self.assertEqual(run(mp4gen.build(esds_type=obj))[0]["audio"][0]["codec"], expect)

    def test_mp4a_without_a_readable_esds_is_aac(self):
        entry = mp4gen.audio_entry(b"mp4a", 2, 44100, box(b"esds", b"\x00\x00\x00\x00\x07"))
        data = mp4gen.build(audio=())
        trak = mp4gen.trak(10, b"soun", entry, lang="eng", timescale=44100, duration=44100)
        i = data.index(b"mvhd") - 4
        j = data.index(b"trak") - 4
        moov_start = data.index(b"moov") - 4
        size = int.from_bytes(data[moov_start:moov_start + 4], "big")
        patched = (data[:moov_start] + u32(size + len(trak)) + data[moov_start + 4:moov_start + size] + trak
                   + data[moov_start + size:])
        self.assertTrue(i and j)
        result, _ = run(patched)       # sample offsets are stale, so only the audio list is asserted
        self.assertEqual((result["audio"][0]["codec"], result["audio"][0]["sample_rate"]), ("aac", 44100))

    def test_quicktime_sound_description_version_1(self):
        entry = mp4gen.audio_entry(b"mp4a", 2, 48000, mp4gen.esds(0x69), version=1)
        data = mp4gen.build(audio=())
        trak = mp4gen.trak(10, b"soun", entry, lang="jpn", timescale=48000, duration=48000)
        moov_start = data.index(b"moov") - 4
        size = int.from_bytes(data[moov_start:moov_start + 4], "big")
        patched = (data[:moov_start] + u32(size + len(trak)) + data[moov_start + 4:moov_start + size] + trak
                   + data[moov_start + size:])
        result, _ = run(patched)
        self.assertEqual((result["audio"][0]["codec"], result["audio"][0]["channels"]), ("mp3", 2))

    def test_language_decoding(self):
        self.assertEqual(mp4probe._language(0x55C4), "und")
        self.assertEqual(mp4probe._language(mp4gen.pack_lang("jpn")[0] << 8 | mp4gen.pack_lang("jpn")[1]), "jpn")
        for bad in (0, 0x7FFF, None, 0x8000):
            self.assertEqual(mp4probe._language(bad), "und")

    def test_chapters(self):
        self.assertEqual(run(mp4gen.build())[0]["chapters"], {"present": False, "count": 0})
        self.assertEqual(run(mp4gen.build(chapters=3))[0]["chapters"], {"present": True, "count": 3})
        result, _ = run(mp4gen.build(chapter_track=True))
        self.assertEqual(result["chapters"], {"present": True, "count": 5})
        self.assertEqual([s["track"] for s in result["subtitles"]], [30])     # the chapter track is not a subtitle

    def test_encoder_tool_string(self):
        self.assertEqual(run(mp4gen.build(tool_style="qt", tool="Kura Writer 1.0"))[0]["writing_app"],
                         "Kura Writer 1.0")
        self.assertIsNone(run(mp4gen.build(tool=None))[0]["writing_app"])
        self.assertIsNone(run(mp4gen.build())[0]["muxing_app"])

    def test_a_still_image_track_does_not_replace_the_video(self):
        still = mp4gen.trak(5, b"vide", mp4gen.visual_entry(b"mjpa", 300, 300), samples=1, timescale=1000)
        data = mp4gen.build(extra_moov=still)
        result, _ = run(data)
        self.assertEqual((result["video"]["track"], result["video"]["codec"]), (1, "h264"))
        self.assertIn("multiple_video_tracks", result["warnings"])

    def test_disabled_only_video_track_is_still_reported(self):
        result, _ = run(mp4gen.build(video_enabled=False))
        self.assertEqual(result["video"]["codec"], "h264")
        self.assertIn("video_track_disabled", result["warnings"])

    def test_no_video_track(self):
        data = mp4gen.build()
        # Replace the video handler type: nothing is video any more.
        result, _ = run(data.replace(b"vide", b"vidX"))
        self.assertIsNone(result["video"])
        self.assertEqual(len(result["audio"]), 1)


class Fragmented(unittest.TestCase):
    def test_fragmented_file_reports_moov_and_warns(self):
        data = mp4gen.build(fragmented=True) + box(b"moof", bytes(40)) + box(b"mdat", bytes(50))
        result, _ = run(data)
        self.assertEqual(result["status"], "ok")
        self.assertIn("fragmented_mp4", result["warnings"])
        self.assertEqual(result["duration_s"], 1420.0)                 # from mehd: mvhd says 0
        self.assertEqual(result["video"]["codec"], "h264")

    def test_fragments_are_not_walked(self):
        many = b"".join(box(b"moof", bytes(8)) + box(b"mdat", bytes(8)) for _ in range(5000))
        data = mp4gen.build(fragmented=True) + many
        result, src = run(data)
        self.assertIn("fragmented_mp4", result["warnings"])
        self.assertNotIn("element_limit", result["warnings"])
        self.assertLess(len(src.reads), 200)

    def test_a_fragment_before_the_movie_box(self):
        data = mp4gen.FTYP + box(b"moof", bytes(40)) + box(b"mdat", bytes(50))
        result, _ = run(data)
        self.assertEqual(result["status"], "invalid")
        self.assertIn("fragmented_mp4", result["warnings"])
        self.assertIn("no_moov", result["warnings"])


class Hostile(unittest.TestCase):
    def check(self, data, **kw):
        result, src = run(data, **kw)
        self.assertIn(result["status"], ("ok", "partial", "invalid", "unsupported_container"))
        self.assertNotIn("internal_error", result["warnings"])
        self.assertTrue(printable(result))
        self.assertLessEqual(src.largest, mp4probe.CLUSTER_CAP)
        self.assertTrue(all(0 <= o < max(len(data), 1) and o + n <= len(data) for o, n in src.reads))
        json.dumps(result)
        return result

    def test_every_truncation_of_a_valid_file(self):
        data = mp4gen.build(faststart=False)
        for cut in list(range(0, 200)) + list(range(200, len(data), 7)):
            with self.subTest(cut=cut):
                self.check(data[:cut])
        data = mp4gen.build()
        for cut in range(0, len(data), 5):
            self.check(data[:cut])

    def test_truncated_moov_is_partial_with_what_survived(self):
        data = mp4gen.build(faststart=False)
        cut = data.index(b"stbl")                       # inside the first trak's tables
        result = self.check(data[:cut])
        self.assertEqual(result["status"], "partial")
        self.assertIn("truncated", result["warnings"])
        self.assertEqual(result["duration_s"], 1420.0)

    def test_a_truncated_file_with_no_moov_is_invalid(self):
        data = mp4gen.build(faststart=False, mdat_pad=1000)
        result = self.check(data[:len(mp4gen.FTYP) + 100])
        self.assertEqual(result["status"], "invalid")
        self.assertIn("truncated", result["warnings"])
        self.assertIn("no_moov", result["warnings"])

    def test_random_bytes_behind_a_valid_ftyp(self):
        rng = random.Random(7)
        for _ in range(300):
            self.check(mp4gen.FTYP + bytes(rng.randrange(256) for _ in range(rng.randrange(0, 400))))

    def test_random_corruption_of_a_valid_file(self):
        rng = random.Random(11)
        good = mp4gen.build()
        for _ in range(600):
            data = bytearray(good)
            for _ in range(rng.randrange(1, 6)):
                data[rng.randrange(len(data))] = rng.randrange(256)
            self.check(bytes(data))

    def test_huge_declared_sizes(self):
        for size in (0xFFFFFFFF, 0x7FFFFFFF, 0xFFFFFFF0):
            with self.subTest(size=size):
                r = self.check(mp4gen.FTYP + u32(size) + b"moov" + bytes(100))
                self.assertIn("truncated", r["warnings"])
                r = self.check(mp4gen.FTYP + u32(size) + b"mdat" + bytes(100))
                self.assertIn("truncated", r["warnings"])
        for big in (1 << 63, (1 << 64) - 1, 1 << 40):
            r = self.check(mp4gen.FTYP + u32(1) + b"moov" + u64(big) + bytes(100))
            self.assertIn("truncated", r["warnings"])
        data = mp4gen.build()
        self.check(data.replace(b"stsd", b"stsd", 1).replace(u32(1) + b"\x00", u32(0xFFFFFFFF) + b"\x00", 1))

    def test_impossible_box_sizes(self):
        for size in (2, 4, 7):
            r = self.check(mp4gen.FTYP + u32(size) + b"moov" + bytes(100))
            self.assertIn("invalid_box", r["warnings"])
        r = self.check(mp4gen.FTYP + u32(1) + b"moov" + u64(3) + bytes(100))        # largesize below the header
        self.assertIn("invalid_box", r["warnings"])
        r = self.check(mp4gen.FTYP + u32(1) + b"moov" + bytes(3))                    # cut inside the largesize
        self.assertIn("truncated", r["warnings"])

    def test_a_box_that_does_not_advance_cannot_loop(self):
        # size 8 boxes of zero payload, one after another: each advances by its own size.
        r = self.check(mp4gen.FTYP + box(b"free") * 30_000)
        self.assertEqual((r["status"], "element_limit" in r["warnings"]), ("partial", True))
        self.assertEqual(r["bytes_read"] < 400_000, True)

    def test_many_tracks_are_capped(self):
        trak = mp4gen.trak(1, b"vide", mp4gen.visual_entry(b"avc1", 16, 16, mp4gen.avcc()))
        data = mp4gen.FTYP + box(b"moov", mp4gen.mvhd() + trak * 500)
        r = self.check(data)
        self.assertEqual((r["status"], "tracks_truncated" in r["warnings"]), ("partial", True))

    def test_a_moov_nested_in_moov_and_repeated_children_are_ignored(self):
        moov = box(b"moov", mp4gen.mvhd(1000, 1000) + box(b"moov", mp4gen.mvhd(5, 5)) + mp4gen.mvhd(7, 7))
        r = self.check(mp4gen.FTYP + moov)
        self.assertEqual(r["duration_s"], 1.0)               # the first mvhd wins; nested boxes are not entered

    def test_hostile_sample_tables(self):
        data = mp4gen.build()
        # stts/stsz/stco counts that promise far more than the box holds.
        for tag in (b"stts", b"stsz", b"stco"):
            i = data.index(tag) + 4
            hacked = data[:i + 4] + u32(0xFFFFFFFF) + data[i + 8:]
            self.check(hacked)
        # a first-chunk offset beyond the end of the file
        i = data.index(b"stco") + 12
        r = self.check(data[:i] + u32(0xFFFFFFF0) + data[i + 4:])
        self.assertIn("bad_sample_offset", r["warnings"])
        self.assertIsNone(r["encoder"])

    def test_zero_timescales_and_durations_do_not_divide(self):
        data = mp4gen.build()
        i = data.index(b"mvhd") + 4 + 12
        self.check(data[:i] + u32(0) + data[i + 4:])
        i = data.index(b"mdhd") + 4 + 12
        r = self.check(data[:i] + u32(0) + u32(0) + data[i + 8:])
        self.assertEqual(r["video"]["codec"], "h264")

    def test_garbage_in_text_fields_is_made_printable(self):
        data = mp4gen.build(tool="Kura\x07\x1b[31m Writer\x00hidden")
        r = self.check(data)
        self.assertTrue(printable(r))
        self.assertEqual(r["writing_app"], "Kura??[31m Writer")

    def test_a_deeply_nested_stsd_entry_does_not_recurse(self):
        nest = b"x" * 8
        for _ in range(2000):
            nest = box(b"avcC", nest)
        entry = mp4gen.visual_entry(b"avc1", 16, 16, nest)
        trak = mp4gen.trak(1, b"vide", entry)
        t0 = time.time()
        r = self.check(mp4gen.FTYP + box(b"moov", mp4gen.mvhd() + trak))
        self.assertLess(time.time() - t0, 2)
        self.assertEqual(r["video"]["codec"], "h264")

    def test_stsd_larger_than_its_cap_is_partial(self):
        entry = mp4gen.visual_entry(b"avc1", 16, 16, mp4gen.avcc() + box(b"free", bytes(80_000)))
        r = self.check(mp4gen.FTYP + box(b"moov", mp4gen.mvhd() + mp4gen.trak(1, b"vide", entry)))
        self.assertEqual(r["status"], "partial")
        self.assertIn("stsd_truncated", r["warnings"])

    def test_very_small_and_empty_inputs(self):
        for tiny in (b"", b"\x00", b"abc", b"\x00\x00\x00\x08ftyp"[:7]):
            self.assertEqual(run(tiny)[0]["status"], "invalid")
        self.assertEqual(run(b"\x00\x00\x00\x08ftyp")[0]["status"], "invalid")      # a bare header: no movie box
        self.assertIn("no_moov", run(b"\x00\x00\x00\x08ftyp")[0]["warnings"])

    def test_not_an_mp4_is_unsupported(self):
        for data in (b"Kura not a video file at all" * 4, mkvgen.build()):
            r = run(data)[0]
            self.assertEqual((r["status"], r["container"]), ("unsupported_container", "unknown"))

    def test_a_short_read_is_reported_not_trusted(self):
        data = mp4gen.build()
        src = Source(data)

        def stingy(offset, n):
            return src(offset, n)[:max(n // 2, 0)] if offset > 40 else src(offset, n)

        r = probe(stingy, len(data))
        self.assertIn("truncated", r["warnings"])
        self.assertNotIn("internal_error", r["warnings"])

    def test_the_source_failing_propagates_to_the_caller(self):
        def broken(offset, n):
            raise OSError("boom")

        with self.assertRaises(OSError):
            probe(broken, 100)

    def test_argument_errors(self):
        for size in (-1, "x"):
            with self.assertRaises(ValueError):
                probe(lambda o, n: b"", size)
        with self.assertRaises(ValueError):
            probe(lambda o, n: b"", 1, max_bytes=-1)


class Budget(unittest.TestCase):
    def test_total_requested_never_exceeds_max_bytes(self):
        for data in (mp4gen.build(), mp4gen.build(faststart=False, mdat_pad=5000), mp4gen.build(codec="hevc")):
            for budget in (0, 1, 7, 8, 15, 16, 17, 40, 100, 300, 1000, 1500, 2000, 1 << 20):
                with self.subTest(budget=budget):
                    r, src = run(data, max_bytes=budget)
                    self.assertLessEqual(src.total, budget)
                    self.assertLessEqual(r["bytes_read"], budget)
                    self.assertNotIn("internal_error", r["warnings"])

    def test_a_tiny_budget_is_partial_with_a_warning(self):
        r, _ = run(mp4gen.build(), max_bytes=100)
        self.assertEqual(r["status"], "partial")
        self.assertIn("budget_exhausted", r["warnings"])

    def test_the_default_budget_is_plenty_for_a_large_moov(self):
        # 100 000 sample-table entries in the video track: skipped by size, never read.
        big = mp4gen.full(b"stts", u32(100_000) + bytes(800_000))
        entry = mp4gen.visual_entry(b"avc1", 16, 16, mp4gen.avcc())
        stbl = mp4gen.stsd(entry) + big + mp4gen.stsz(2, 8) + mp4gen.stco(0)
        trak = box(b"trak", mp4gen.tkhd(1, True, 16, 16) + box(b"mdia", mp4gen.mdhd(1000, 1000)
                   + mp4gen.hdlr(b"vide") + box(b"minf", box(b"stbl", stbl))))
        r, src = run(mp4gen.FTYP + box(b"moov", mp4gen.mvhd() + trak) + box(b"mdat", bytes(64)), max_bytes=64 << 10)
        self.assertEqual(r["video"]["codec"], "h264")
        self.assertNotIn("budget_exhausted", r["warnings"])
        self.assertLess(src.total, 4 << 10)


class Dispatch(unittest.TestCase):
    def go(self, data, **kw):
        src = Source(data)
        return probe_mod.probe_container(src, src.size, **kw), src

    def test_dispatch_by_magic(self):
        self.assertEqual(self.go(mkvgen.build())[0]["container"], "matroska")
        self.assertEqual(self.go(mkvgen.build(doc_type="webm"))[0]["container"], "webm")
        r, _ = self.go(mp4gen.build())
        self.assertEqual((r["container"], r["status"], r["video"]["codec"]), ("mp4", "ok", "h264"))
        for first in (b"free", b"skip", b"wide", b"mdat", b"moov"):
            r, _ = self.go(box(first, bytes(20)))
            self.assertEqual(r["container"], "mp4", first)
        for junk in (b"Kura not a video file at all" * 4, b"RIFF" + bytes(60), bytes(64), b"\x00\x00\x00\x18ftyq" + bytes(40)):
            r, _ = self.go(junk)
            self.assertEqual((r["status"], r["container"]), ("unsupported_container", "unknown"))

    def test_the_result_equals_the_direct_parser(self):
        mkv, mp4 = mkvgen.build(), mp4gen.build()
        self.assertEqual(self.go(mkv)[0], mkvprobe.probe(Source(mkv), len(mkv)))
        self.assertEqual(self.go(mp4)[0], mp4probe.probe(Source(mp4), len(mp4)))

    def test_matroska_magic_wins_over_an_mp4_looking_offset_4(self):
        data = b"\x1a\x45\xdf\xa3ftyp" + bytes(40)
        self.assertNotEqual(self.go(data)[0]["container"], "mp4")

    def test_the_sniffed_bytes_count_against_the_budget(self):
        for data in (mp4gen.build(), mkvgen.build(), b"junk" * 20):
            for budget in (0, 3, 8, 15, 16, 20, 200):
                r, src = self.go(data, max_bytes=budget)
                self.assertLessEqual(src.total, budget, (budget, len(data)))
                self.assertLessEqual(r["bytes_read"], budget)

    def test_tiny_files(self):
        for tiny in (b"", b"\x00", b"abc", b"\x00\x00\x00\x08ftyp", b"\x1a\x45\xdf\xa3"):
            r, _ = self.go(tiny)
            self.assertEqual(r["status"], "invalid", tiny)

    def test_argument_errors_still_raise(self):
        with self.assertRaises(ValueError):
            probe_mod.probe_container(lambda o, n: b"", -1)
        with self.assertRaises(ValueError):
            probe_mod.probe_container(lambda o, n: b"", 10, max_bytes=-1)

    def test_the_module_is_pure(self):
        for name in ("os", "sys", "socket", "subprocess", "open", "io", "http", "urllib"):
            self.assertFalse(hasattr(mp4probe, name), name)


if __name__ == "__main__":
    unittest.main()
